//! Tests for V8 Fast API callbacks generated by `#[jsg_method]`.

use std::cell::Cell;

use jsg::ExceptionType;
use jsg::Number;
use jsg_macros::jsg_method;
use jsg_macros::jsg_resource;

#[jsg_resource]
struct FastResource {
    base: i32,
    touched: Cell<u32>,
}

#[jsg_resource]
impl FastResource {
    #[jsg_method]
    pub fn add(&self, a: i32, b: i32) -> Number {
        Number::new(f64::from(self.base) + f64::from(a) + f64::from(b))
    }

    #[jsg_method]
    pub fn id_i32(&self, x: i32) -> Number {
        Number::new(f64::from(x))
    }

    #[jsg_method]
    pub fn id_u32(&self, x: u32) -> Number {
        Number::new(f64::from(x))
    }

    #[jsg_method]
    pub fn id_number(&self, x: Number) -> Number {
        x
    }

    #[jsg_method]
    pub fn id_bool(&self, x: bool) -> bool {
        x
    }

    #[jsg_method]
    pub fn touch(&self) {
        self.touched.set(self.touched.get() + 1);
    }

    #[jsg_method]
    pub fn touched(&self) -> Number {
        Number::from(self.touched.get())
    }

    #[jsg_method]
    pub fn panic_on(&self, code: i32) -> Number {
        assert!(code <= 0, "intentional panic in a fast callback");
        Number::new(f64::from(code))
    }

    #[jsg_method]
    pub fn hypot(a: Number, b: Number) -> Number {
        Number::new(a.value().hypot(b.value()))
    }
}

/// Defines `hot(...)` with `body`, calls it once with `warmup` so V8 collects feedback, optimizes
/// it, and returns the source of the call `hot(args)`.
fn optimized(params: &str, body: &str, warmup: &str, args: &str) -> String {
    format!(
        "function hot({params}) {{ {body} }}
         %PrepareFunctionForOptimization(hot);
         hot({warmup});
         %OptimizeFunctionOnNextCall(hot);
         hot({args})"
    )
}

/// Runs `f` and counts the fast callbacks it ran, or returns `None` for the count in builds
/// without debug assertions, which don't count them.
#[cfg(debug_assertions)]
fn count_fast_calls<T>(f: impl FnOnce() -> T) -> (T, Option<u64>) {
    let before = jsg::fast_api::call_count();
    let result = f();
    (result, Some(jsg::fast_api::call_count() - before))
}

#[cfg(not(debug_assertions))]
fn count_fast_calls<T>(f: impl FnOnce() -> T) -> (T, Option<u64>) {
    (f(), None)
}

fn set_resource(lock: &mut jsg::Lock, ctx: &crate::EvalContext<'_>, base: i32) {
    let resource = jsg::Rc::new(FastResource {
        base,
        touched: Cell::new(0),
    });
    ctx.set_global(lock, "r", resource);
    let constructor = jsg::resource::function_template_of::<FastResource>(lock);
    ctx.set_global(lock, "FastResource", constructor);
}

#[test]
fn instance_method_takes_fast_path() {
    let harness = crate::Harness::with_fast_api();
    harness.run_in_context(|lock, ctx| {
        set_resource(lock, ctx, 100);
        let (result, fast_calls) = count_fast_calls(|| {
            ctx.eval::<Number>(
                lock,
                &optimized("a, b", "return r.add(a, b);", "1, 2", "3, 4"),
            )
            .unwrap()
        });
        assert!((result.value() - 107.0).abs() < f64::EPSILON);
        assert_ne!(fast_calls, Some(0));
        Ok(())
    });
}

#[test]
fn void_method_takes_fast_path() {
    let harness = crate::Harness::with_fast_api();
    harness.run_in_context(|lock, ctx| {
        set_resource(lock, ctx, 0);
        let (touched, fast_calls) = count_fast_calls(|| {
            ctx.eval::<Number>(
                lock,
                &format!("{}; r.touched()", optimized("", "r.touch();", "", "")),
            )
            .unwrap()
        });
        assert!((touched.value() - 2.0).abs() < f64::EPSILON);
        assert_ne!(fast_calls, Some(0));
        Ok(())
    });
}

#[test]
fn static_method_takes_fast_path() {
    let harness = crate::Harness::with_fast_api();
    harness.run_in_context(|lock, ctx| {
        set_resource(lock, ctx, 0);
        let (result, fast_calls) = count_fast_calls(|| {
            ctx.eval::<Number>(
                lock,
                &optimized("a, b", "return FastResource.hypot(a, b);", "1, 1", "3, 4"),
            )
            .unwrap()
        });
        assert!((result.value() - 5.0).abs() < f64::EPSILON);
        assert_ne!(fast_calls, Some(0));
        Ok(())
    });
}

#[test]
fn no_fast_path_unless_enabled() {
    let harness = crate::Harness::new();
    harness.run_in_context(|lock, ctx| {
        set_resource(lock, ctx, 100);
        let (result, fast_calls) = count_fast_calls(|| {
            ctx.eval::<Number>(
                lock,
                &optimized("a, b", "return r.add(a, b);", "1, 2", "3, 4"),
            )
            .unwrap()
        });
        assert!((result.value() - 107.0).abs() < f64::EPSILON);
        assert_eq!(fast_calls.unwrap_or(0), 0);
        Ok(())
    });
}

/// Each case gives the same result or error on both paths, and takes the fast path if `expect_fast`.
#[test]
fn fast_and_slow_paths_agree() {
    let cases = [
        ("idI32", "1", "7", true),
        ("idI32", "1", "-7", true),
        ("idI32", "1", "1.9", true),
        ("idI32", "1", "-1.9", true),
        ("idI32", "1", "-0", true),
        ("idI32", "1", "NaN", true),
        ("idI32", "1", "Infinity", true),
        ("idI32", "1", "2 ** 31", true),
        ("idI32", "1", "2 ** 31 - 0.5", true),
        ("idI32", "1", "-(2 ** 31) - 0.5", true),
        ("idI32", "1", "'7'", false),
        ("idI32", "1", "({ valueOf() { return 3; } })", false),
        ("idI32", "1", "undefined", false),
        ("idU32", "1", "2 ** 32 - 1", true),
        ("idU32", "1", "2 ** 32", true),
        ("idU32", "1", "2 ** 32 - 0.5", true),
        ("idU32", "1", "-1", true),
        ("idU32", "1", "-0.5", true),
        ("idU32", "1", "NaN", true),
        ("idNumber", "0.5", "-2.25", true),
        ("idNumber", "0.5", "NaN", true),
        ("idNumber", "0.5", "-Infinity", true),
        ("idNumber", "0.5", "'2.5'", false),
        ("idBool", "true", "false", true),
        ("idBool", "true", "0", true),
        ("idBool", "true", "'yes'", true),
        ("idBool", "true", "null", true),
    ];

    for (method, warmup, arg, expect_fast) in cases {
        let source = optimized("x", &format!("return String(r.{method}(x));"), warmup, arg);
        let slow = crate::Harness::new();
        let mut slow_result = None;
        slow.run_in_context(|lock, ctx| {
            set_resource(lock, ctx, 0);
            slow_result = Some(
                ctx.eval::<String>(lock, &source)
                    .map_err(|e| e.unwrap_jsg_err(lock).message),
            );
            Ok(())
        });

        let fast = crate::Harness::with_fast_api();
        fast.run_in_context(|lock, ctx| {
            set_resource(lock, ctx, 0);
            let (fast_result, fast_calls) = count_fast_calls(|| {
                ctx.eval::<String>(lock, &source)
                    .map_err(|e| e.unwrap_jsg_err(lock).message)
            });
            assert_eq!(Some(fast_result), slow_result, "{method}({arg})");
            if let Some(fast_calls) = fast_calls {
                let took_fast_path = fast_calls > 0;
                assert_eq!(
                    took_fast_path, expect_fast,
                    "{method}({arg}): fast path taken = {took_fast_path}"
                );
            }
            Ok(())
        });
    }
}

/// V8 checks the receiver against the method's signature before a fast call, so a wrong receiver
/// goes to the slow callback, which throws.
#[test]
fn wrong_receiver_takes_slow_path_and_throws() {
    let harness = crate::Harness::with_fast_api();
    harness.run_in_context(|lock, ctx| {
        set_resource(lock, ctx, 0);
        let (err, fast_calls) = count_fast_calls(|| {
            ctx.eval::<Number>(
                lock,
                &optimized(
                    "o",
                    "return FastResource.prototype.idI32.call(o, 1);",
                    "r",
                    "{}",
                ),
            )
            .unwrap_err()
            .unwrap_jsg_err(lock)
        });
        assert_eq!(err.name, ExceptionType::TypeError);
        assert!(
            err.message.to_lowercase().contains("illegal invocation"),
            "unexpected error message: {}",
            err.message
        );
        assert_eq!(fast_calls.unwrap_or(0), 0);
        Ok(())
    });
}

#[test]
fn panic_in_fast_callback_is_an_internal_error() {
    let harness = crate::Harness::with_fast_api();
    harness.run_in_context(|lock, ctx| {
        set_resource(lock, ctx, 0);
        let (err, fast_calls) = count_fast_calls(|| {
            ctx.eval::<Number>(
                lock,
                &optimized("code", "return r.panicOn(code);", "0", "1"),
            )
            .unwrap_err()
            .unwrap_jsg_err(lock)
        });
        assert_ne!(fast_calls, Some(0));
        assert!(
            err.message.contains("internal error"),
            "unexpected error message: {:?}",
            err.message
        );
        assert!(
            !err.message.contains("intentional panic"),
            "raw panic message must not be exposed to JS, got: {:?}",
            err.message
        );
        Ok(())
    });
}
